import json
import os
import secrets
import time
from collections import deque
from datetime import datetime, timezone
from pathlib import Path
from threading import Lock
from typing import Any

from ...config import app_data_dir

PLUGIN_VERSION = "0.1.0"

PLUGIN_SOURCE = r'''-- Kova Bridge for Roblox Studio
-- Generated by Kova Hub. Local-only bridge; do not share this file.
local HttpService = game:GetService("HttpService")
local ServerScriptService = game:GetService("ServerScriptService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerStorage = game:GetService("ServerStorage")
local StarterPlayer = game:GetService("StarterPlayer")
local StarterGui = game:GetService("StarterGui")
local StarterPack = game:GetService("StarterPack")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")

local BASE = "http://127.0.0.1:8765/roblox"
local TOKEN = "__KOVA_TOKEN__"
local VERSION = "__KOVA_PLUGIN_VERSION__"
local MAX_SOURCE = 200000

local toolbar = plugin:CreateToolbar("Kova")
local button = toolbar:CreateButton("Kova Bridge", "Kova bridge status", "")
local running = true
local lastStatus = "connecting"

local services = {
	Workspace = Workspace,
	ServerScriptService = ServerScriptService,
	ReplicatedStorage = ReplicatedStorage,
	ServerStorage = ServerStorage,
	StarterPlayer = StarterPlayer,
	StarterGui = StarterGui,
	StarterPack = StarterPack,
	Lighting = Lighting,
}

local function send(path, method, body)
	local ok, response = pcall(function()
		return HttpService:RequestAsync({
			Url = BASE .. path,
			Method = method or "GET",
			Headers = {
				["Content-Type"] = "application/json",
				["X-Kova-Roblox-Token"] = TOKEN,
			},
			Body = body and HttpService:JSONEncode(body) or nil,
		})
	end)
	if not ok then
		return nil, tostring(response)
	end
	if not response.Success then
		return nil, "HTTP " .. tostring(response.StatusCode) .. ": " .. tostring(response.Body)
	end
	local decoded, decodeError = pcall(function()
		return HttpService:JSONDecode(response.Body)
	end)
	if not decoded then
		return nil, tostring(decodeError)
	end
	return decoded, nil
end

local function resolve(path)
	if type(path) ~= "string" or path == "" then
		error("path is empty")
	end
	local parts = string.split(path, ".")
	local current = services[parts[1]]
	if not current then
		error("unknown service: " .. tostring(parts[1]))
	end
	for index = 2, #parts do
		local child = current:FindFirstChild(parts[index])
		if not child then
			error("not found: " .. path)
		end
		current = child
	end
	return current
end

local function ensureFolder(parent, name)
	local existing = parent:FindFirstChild(name)
	if existing then
		if not existing:IsA("Folder") then
			error(name .. " already exists and is not a Folder")
		end
		return existing
	end
	local folder = Instance.new("Folder")
	folder.Name = name
	folder.Parent = parent
	return folder
end

local function createScript(command)
	local service = services[command.service]
	if not service then
		error("unknown service: " .. tostring(command.service))
	end
	local source = tostring(command.source or "")
	if #source > MAX_SOURCE then
		error("source is too large")
	end
	local parent = service
	for _, part in ipairs(string.split(tostring(command.path or ""), ".")) do
		if part ~= "" then
			parent = ensureFolder(parent, part)
		end
	end
	local name = tostring(command.name or "KovaScript")
	local existing = parent:FindFirstChild(name)
	if existing then
		existing:Destroy()
	end
	local scriptType = tostring(command.script_type or "Script")
	local instance
	if scriptType == "LocalScript" then
		instance = Instance.new("LocalScript")
	elseif scriptType == "ModuleScript" then
		instance = Instance.new("ModuleScript")
	else
		instance = Instance.new("Script")
	end
	instance.Name = name
	instance.Source = source
	instance.Parent = parent
	return instance:GetFullName()
end

local function createFolder(command)
	local service = services[command.service]
	if not service then
		error("unknown service: " .. tostring(command.service))
	end
	local parent = service
	for _, part in ipairs(string.split(tostring(command.path or ""), ".")) do
		if part ~= "" then
			parent = ensureFolder(parent, part)
		end
	end
	local name = tostring(command.name or "Folder")
	local folder = ensureFolder(parent, name)
	return folder:GetFullName()
end

local function setSource(command)
	local instance = resolve(tostring(command.path or ""))
	if not instance:IsA("LuaSourceContainer") then
		error("not a script")
	end
	local source = tostring(command.source or "")
	if #source > MAX_SOURCE then
		error("source is too large")
	end
	instance.Source = source
	return instance:GetFullName()
end

local function deleteObject(command)
	local instance = resolve(tostring(command.path or ""))
	instance:Destroy()
	return "deleted"
end

local function createPart(command)
	local parent = Workspace
	if command.parent then
		parent = resolve(tostring(command.parent))
	end
	local part = Instance.new("Part")
	part.Name = tostring(command.name or "Part")
	part.Anchored = true
	part.CanCollide = command.can_collide == true
	part.Size = Vector3.new(
		tonumber(command.size_x) or 4,
		tonumber(command.size_y) or 1,
		tonumber(command.size_z) or 2
	)
	part.Position = Vector3.new(
		tonumber(command.x) or 0,
		tonumber(command.y) or 4,
		tonumber(command.z) or 0
	)
	part.Color = Color3.fromRGB(
		tonumber(command.r) or 40,
		tonumber(command.g) or 40,
		tonumber(command.b) or 40
	)
	part.Material = Enum.Material.SmoothPlastic
	part.Parent = parent
	return part:GetFullName()
end

local function execute(command)
	local kind = tostring(command.type or "")
	if kind == "ping" then
		return "pong"
	elseif kind == "create_script" then
		return createScript(command)
	elseif kind == "create_folder" then
		return createFolder(command)
	elseif kind == "set_source" then
		return setSource(command)
	elseif kind == "delete" then
		return deleteObject(command)
	elseif kind == "create_part" then
		return createPart(command)
	elseif kind == "playtest" then
		local ok, err = pcall(function()
			plugin:StartPlaytest()
		end)
		if not ok then
			error(tostring(err))
		end
		return "playtest started"
	end
	error("unknown command: " .. kind)
end

local function poll()
	while running do
		local data, err = send("/commands")
		if data and data.command then
			local command = data.command
			local ok, result = pcall(function()
				return execute(command)
			end)
			send("/results", "POST", {
				id = command.id,
				ok = ok,
				result = ok and tostring(result) or "",
				error = ok and "" or tostring(result),
				plugin_version = VERSION,
			})
			lastStatus = ok and ("ok: " .. command.type) or ("error: " .. tostring(result))
		elseif err then
			lastStatus = err
		end
		task.wait(0.6)
	end
end

button.Click:Connect(function()
	local data = send("/status")
	if data then
		lastStatus = data.connected and "connected" or "waiting"
	end
	print("[Kova] " .. lastStatus)
end)

task.spawn(poll)
print("[Kova] Roblox bridge " .. VERSION .. " started")
'''


class RobloxBridge:
    def __init__(self) -> None:
        self._lock = Lock()
        self._queue: deque[dict[str, Any]] = deque(maxlen=100)
        self._pending: dict[str, dict[str, Any]] = {}
        self._results: dict[str, dict[str, Any]] = {}
        self._last_seen = 0.0
        self._plugin_version = ""
        self._last_error = ""
        self._token = self._load_token()

    def _token_file(self) -> Path:
        return app_data_dir() / "roblox-bridge.json"

    def _load_token(self) -> str:
        override = os.environ.get("KOVA_ROBLOX_TOKEN", "").strip()
        if override:
            return override
        path = self._token_file()
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            token = str(data.get("token") or "").strip()
            if token:
                return token
        except (OSError, ValueError):
            pass
        token = secrets.token_urlsafe(24)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps({"token": token}, indent=2) + "\n",
            encoding="utf-8",
        )
        return token

    def token(self) -> str:
        return self._token

    def install_plugin(self) -> dict[str, Any]:
        root = Path(os.environ.get("LOCALAPPDATA") or Path.home() / "AppData" / "Local")
        plugins = root / "Roblox" / "Plugins"
        plugins.mkdir(parents=True, exist_ok=True)
        target = plugins / "KovaBridge.lua"
        source = PLUGIN_SOURCE.replace("__KOVA_TOKEN__", self._token).replace(
            "__KOVA_PLUGIN_VERSION__", PLUGIN_VERSION
        )
        target.write_text(source, encoding="utf-8")
        return {
            "ok": True,
            "path": str(target),
            "version": PLUGIN_VERSION,
            "message": "Плагин установлен. Перезапусти Roblox Studio и включи HTTP-запросы.",
        }

    def status(self) -> dict[str, Any]:
        with self._lock:
            age = time.monotonic() - self._last_seen if self._last_seen else 9999
            return {
                "connected": age < 6,
                "last_seen_seconds": round(age, 1) if self._last_seen else None,
                "plugin_version": self._plugin_version,
                "pending": len(self._queue),
                "last_error": self._last_error,
                "token_configured": bool(self._token),
            }

    def enqueue(self, command: dict[str, Any]) -> dict[str, Any]:
        kind = str(command.get("type") or "").strip()
        allowed = {
            "ping",
            "create_script",
            "create_folder",
            "set_source",
            "delete",
            "create_part",
            "playtest",
        }
        if kind not in allowed:
            raise ValueError("unknown Roblox command")
        command_id = "rbx_" + secrets.token_hex(8)
        row = {"id": command_id, "type": kind, **command}
        row.pop("type", None)
        row["type"] = kind
        with self._lock:
            self._queue.append(row)
            self._pending[command_id] = row
        return {"ok": True, "id": command_id, "command": row}

    def next_command(self, token: str) -> dict[str, Any]:
        if token != self._token:
            raise PermissionError("bad bridge token")
        with self._lock:
            self._last_seen = time.monotonic()
            if not self._queue:
                return {"command": None}
            command = self._queue.popleft()
            return {"command": command}

    def complete(self, token: str, payload: dict[str, Any]) -> dict[str, Any]:
        if token != self._token:
            raise PermissionError("bad bridge token")
        command_id = str(payload.get("id") or "")
        with self._lock:
            self._last_seen = time.monotonic()
            self._plugin_version = str(payload.get("plugin_version") or "")[:80]
            self._pending.pop(command_id, None)
            result = {
                "id": command_id,
                "ok": bool(payload.get("ok")),
                "result": str(payload.get("result") or "")[:4000],
                "error": str(payload.get("error") or "")[:4000],
            }
            self._results[command_id] = result
            if not result["ok"]:
                self._last_error = result["error"]
            return result

    def result(self, command_id: str) -> dict[str, Any] | None:
        with self._lock:
            return self._results.get(command_id)


BRIDGE = RobloxBridge()
